size_t alBfs(const AdjList *l, size_t start, int *order) {
  if (start >= l->n) return 0;
  int *queue = malloc(l->n * sizeof *queue);
  unsigned char *seen = calloc(l->n, 1);
  size_t head = 0, tail = 0, count = 0;
  if (queue == NULL || seen == NULL) { free(queue); free(seen); return 0; }
  queue[tail++] = (int)start;
  seen[start] = 1;
  while (head < tail) {
    int u = queue[head++];
    order[count++] = u;
    for (const AdjEdge *e = l->head[u]; e != NULL; e = e->next)
      if (!seen[e->to]) { seen[e->to] = 1; queue[tail++] = e->to; }
  }
  free(queue);
  free(seen);
  return count;
}

