static void visit(const AdjList *l, size_t u, unsigned char *seen) {
  seen[u] = 1;
  for (const AdjEdge *e = l->head[u]; e != NULL; e = e->next)
    if (!seen[e->to]) visit(l, (size_t)e->to, seen);
}
size_t components(const AdjList *l) {
  unsigned char *seen = calloc(l->n + 1, 1);
  size_t c = 0;
  if (seen == NULL) return 0;
  for (size_t u = 0; u < l->n; u++)
    if (!seen[u]) { c++; visit(l, u, seen); }
  free(seen);
  return c;
}

typedef struct AdjEdge { int to; struct AdjEdge *next; } AdjEdge;
