int alRemove(AdjList *l, size_t u, size_t v) {
  if (u >= l->n || v >= l->n) return 0;
  AdjEdge **pp = &l->head[u];
  while (*pp != NULL && (*pp)->to != (int)v) pp = &(*pp)->next;
  if (*pp == NULL) return 0;
  AdjEdge *dead = *pp;
  *pp = dead->next;
  free(dead);
  return 1;
}

