typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
int ah(const ANode *n) { return n != NULL ? n->h : 0; }
void aupd(ANode *n) {
  int a = ah(n->l), b = ah(n->r);
  n->h = 1 + (a > b ? a : b);
}
int abal(const ANode *n) { return n != NULL ? ah(n->l) - ah(n->r) : 0; }
ANode *anew(int key) {
  ANode *n = malloc(sizeof *n);
  if (n == NULL) return NULL;
  n->key = key;
  n->h = 1;
  n->l = n->r = NULL;
  return n;
}

