int avlHeight(const ANode *t) { return ah(t); }
int avlValid(const ANode *t, int *height) {
  if (t == NULL) { *height = 0; return 1; }
  int hl, hr;
  if (!avlValid(t->l, &hl) || !avlValid(t->r, &hr)) return 0;
  *height = 1 + (hl > hr ? hl : hr);
  return (hl - hr >= -1 && hl - hr <= 1) && *height == t->h;
}

