#define DS_NONE SIZE_MAX
typedef struct { size_t *p; unsigned char *rank; size_t n, count; } DSU;
int dsInit(DSU *d, size_t n) {
  d->p = calloc(n + 1, sizeof *d->p);
  d->rank = calloc(n + 1, 1);
  d->n = n;
  d->count = n;
  if (d->p == NULL || d->rank == NULL) {
    free(d->p);
    free(d->rank);
    d->p = NULL; d->rank = NULL; d->n = d->count = 0;
    return 0;
  }
  for (size_t i = 0; i < n; i++) d->p[i] = i;
  return 1;
}
void dsFree(DSU *d) {
  free(d->p);
  free(d->rank);
  d->p = NULL; d->rank = NULL; d->n = d->count = 0;
}

int dsUnion(DSU *d, size_t a, size_t b) {
  size_t ra = dsFind(d, a), rb = dsFind(d, b);
  if (ra == DS_NONE || rb == DS_NONE || ra == rb) return 0;
  if (d->rank[ra] < d->rank[rb]) { size_t t = ra; ra = rb; rb = t; }
  d->p[rb] = ra;
  if (d->rank[ra] == d->rank[rb]) d->rank[ra]++;
  d->count--;
  return 1;
}

