typedef int (*LessFn)(const Item *, const Item *);
typedef struct { Item *a; size_t n, cap; LessFn less; int nextSeq; } PQ;
int itemLess(const Item *a, const Item *b) {
  if (a->key != b->key) return a->key < b->key;
  return a->seq < b->seq;
}
int itemLessKeyOnly(const Item *a, const Item *b) { return a->key < b->key; }
void pqInit(PQ *q, LessFn less) {
  q->a = NULL; q->n = q->cap = 0; q->less = less; q->nextSeq = 0;
}
int pqPush(PQ *q, long long key, int id) {
  if (q->n == q->cap) {
    size_t nc = q->cap != 0 ? q->cap * 2 : 4;
    Item *p = realloc(q->a, nc * sizeof *p);
    if (p == NULL) return 0;
    q->a = p;
    q->cap = nc;
  }
  Item it = { key, q->nextSeq++, id };
  size_t i = q->n++;
  q->a[i] = it;
  while (i > 0) {
    size_t p = (i - 1) / 2;
    if (!q->less(&q->a[i], &q->a[p])) break;
    Item t = q->a[p]; q->a[p] = q->a[i]; q->a[i] = t;
    i = p;
  }
  return 1;
}
int pqPop(PQ *q, Item *out) {
  if (q->n == 0) return 0;
  *out = q->a[0];
  q->a[0] = q->a[--q->n];
  size_t i = 0;
  for (;;) {
    size_t l = 2 * i + 1, r = l + 1, m = i;
    if (l < q->n && q->less(&q->a[l], &q->a[m])) m = l;
    if (r < q->n && q->less(&q->a[r], &q->a[m])) m = r;
    if (m == i) break;
    Item t = q->a[m]; q->a[m] = q->a[i]; q->a[i] = t;
