size_t mergeK(const int *const arrs[], const size_t lens[], size_t k, int *out) {
  size_t pos[8], total = 0;
  if (k > 8) return 0;
  PQ q;
  pqInit(&q, itemLess);
  for (size_t i = 0; i < k; i++) {
    pos[i] = 0;
    if (lens[i] > 0) { pqPush(&q, arrs[i][0], (int)i); pos[i] = 1; }
  }
  Item it;
  while (pqPop(&q, &it)) {
    out[total++] = (int)it.key;
    size_t i = (size_t)it.id;
    if (pos[i] < lens[i]) pqPush(&q, arrs[i][pos[i]++], it.id);
  }
  pqFree(&q);
  return total;
}

