int trieRemoveRec(TrieNode *n, const char *w, int *removed) {
  if (*w == '\0') {
    if (n->end) { n->end = 0; *removed = 1; }
  } else if (*w >= 'a' && *w <= 'z' && n->next[*w - 'a'] != NULL) {
    if (trieRemoveRec(n->next[*w - 'a'], w + 1, removed)) {
      free(n->next[*w - 'a']);
      n->next[*w - 'a'] = NULL;
    }
  }
  if (n->end) return 0;
  for (int k = 0; k < 26; k++)
    if (n->next[k] != NULL) return 0;
  return 1;
}
