  for (;;) {
    if (*f == '#') return 1;
    if (*f == '+') {
      while (*t && *t != '/') t++;
      f++;
      if (*f == 0) return *t == 0;
      continue;
    }
    if (f[0] == '/' && f[1] == '#' && f[2] == 0 && *t == 0) return 1;
