class LRU
  def initialize(cap)
    @cap = cap
    @map = {}
    @list = DList.new
  end
  def get(k)
    node = @map[k]
    return nil unless node
    @list.remove(node)
    @list.link_after(@list.head, node)
    node.value[1]
  end
  def put(k, v)
    if (node = @map[k])
      @list.remove(node)
      @list.link_after(@list.head, node)
      node.value = [k, v]
      return v
    end
    if @map.size >= @cap
      old = @list.tail.prev
      @list.remove(old)
      @map.delete(old.value[0])
    end
    @map[k] = @list.push_front([k, v])
    v
  end
end

