    if (this.head === this.tail) return undefined;
    const x = this.items.get(this.head);
    this.items.delete(this.head++);
    return x;
  }
  popBack(): T | undefined {
    if (this.head === this.tail) return undefined;
    const x = this.items.get(--this.tail);
    this.items.delete(this.tail);
    return x;
  }
  peekFront(): T | undefined { return this.items.get(this.head); }
  peekBack(): T | undefined { return this.items.get(this.tail - 1); }
  get size(): number { return this.tail - this.head; }
  toArray(): T[] {
    const out: T[] = [];
    for (let i = this.head; i < this.tail; i++) out.push(this.items.get(i) as T);
