  const dq = new Deque<number>();
  const out: number[] = [];
  nums.forEach((x, i) => {
    if (dq.size && (dq.peekFront() as number) <= i - k) dq.popFront();
    while (dq.size && (nums[dq.peekBack() as number] as number) <= x) dq.popBack();
    dq.pushBack(i);
