function zeroOneBad(adj: [number, number][][], src: number): number[] {
  const dist = adj.map(() => Infinity);
  const seen = new Set<number>([src]);
  dist[src] = 0;
  const dq = new Deque<number>();
  dq.pushBack(src);
  while (dq.size) {
    const u = dq.popFront() as number;
    for (const [v, w] of adj[u] as [number, number][]) {
      if (seen.has(v)) continue;
      seen.add(v);
      dist[v] = (dist[u] as number) + w;
      if (w === 0) dq.pushFront(v);
      else dq.pushBack(v);
    }
  }
  return dist;
}

