    const u = dq.popFront() as number;
    for (const [v, w] of adj[u] as [number, number][]) {
      const nd = (dist[u] as number) + w;
      if (nd >= (dist[v] as number)) continue;
      dist[v] = nd;
      if (w === 0) dq.pushFront(v);
      else dq.pushBack(v);
    }
  }
  return dist;
}

