function scc(g: DiGraph): number[][] {
  const seen = new Array<boolean>(g.n).fill(false);
  const order: number[] = [];
  const dfs1 = (u: number): void => {
    seen[u] = true;
    for (const v of g.adj[u] as number[]) if (!seen[v]) dfs1(v);
    order.push(u);
  };
  for (let u = 0; u < g.n; u++) if (!seen[u]) dfs1(u);
  const rev = new DiGraph(g.n);
  g.adj.forEach((row, u) => row.forEach((v) => rev.addEdge(v, u)));
  const done = new Array<boolean>(g.n).fill(false);
  const comps: number[][] = [];
  for (let i = order.length - 1; i >= 0; i--) {
    const s = order[i] as number;
    if (done[s]) continue;
    const comp: number[] = [];
    const dfs2 = (u: number): void => {
      done[u] = true;
      comp.push(u);
      for (const v of rev.adj[u] as number[]) if (!done[v]) dfs2(v);
    };
    dfs2(s);
    comps.push(comp);
  }
  return comps;
}

