function topoSort(g: DiGraph): number[] {
  const indeg = new Array<number>(g.n).fill(0);
  for (const row of g.adj) for (const v of row) indeg[v] = (indeg[v] as number) + 1;
  const queue: number[] = [];
  indeg.forEach((d, u) => { if (d === 0) queue.push(u); });
  for (let i = 0; i < queue.length; i++) {
    for (const v of g.adj[queue[i] as number] as number[]) {
      indeg[v] = (indeg[v] as number) - 1;
      if (indeg[v] === 0) queue.push(v);
    }
  }
  return queue.length === g.n ? queue : [];
}

