    const node: DNode<T> = { value, prev: null, next: this.head };
    if (this.head) this.head.prev = node;
    else this.tail = node;
    this.head = node;
    this.size++;
    return node;
  }
  toArray(): T[] {
    const out: T[] = [];
    for (let n = this.head; n; n = n.next) out.push(n.value);
    return out;
  }
  toArrayReversed(): T[] {
    const out: T[] = [];
    for (let n = this.tail; n; n = n.prev) out.push(n.value);
