class LruCache<K, V> {
  private list = new DoublyLinkedList<[K, V]>();
  private map = new Map<K, DNode<[K, V]>>();
  constructor(private cap: number) {}
  get(k: K): V | undefined {
    const node = this.map.get(k);
    if (!node) return undefined;
    removeNode(this.list, node);
    this.map.set(k, this.list.pushFront(node.value));
    return node.value[1];
  }
  put(k: K, v: V): void {
    const old = this.map.get(k);
    if (old) removeNode(this.list, old);
    this.map.set(k, this.list.pushFront([k, v]));
    if (this.list.size > this.cap) {
      const last = this.list.tail as DNode<[K, V]>;
      removeNode(this.list, last);
      this.map.delete(last.value[0]);
    }
  }
}

