function reverse<T>(l: DLike<T>): void {
  let n = l.head;
  while (n) {
    const next = n.next;
    [n.prev, n.next] = [n.next, n.prev];
    n = next;
  }
  [l.head, l.tail] = [l.tail, l.head];
}

