class MinHeap {
  data: number[] = [];
  get size(): number { return this.data.length; }
  peek(): number | undefined { return this.data[0]; }
  push(x: number): void {
    const d = this.data;
    d.push(x);
    let i = d.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if ((d[p] as number) <= (d[i] as number)) break;
      [d[p], d[i]] = [d[i] as number, d[p] as number];
      i = p;
    }
  }
  pop(): number | undefined {
    const d = this.data;
    if (d.length === 0) return undefined;
    const top = d[0] as number;
    const last = d.pop() as number;
    if (d.length > 0) {
      d[0] = last;
      siftDown(d, 0, d.length);
    }
    return top;
  }
}

