class SegTree {
  n: number;
  tree: number[];
  constructor(a: number[]) {
    this.n = a.length;
    this.tree = new Array<number>(4 * Math.max(1, this.n)).fill(0);
    if (this.n > 0) this.build(a, 1, 0, this.n - 1);
  }
  build(a: number[], node: number, l: number, r: number): void {
    if (l === r) {
      this.tree[node] = a[l] as number;
      return;
    }
    const mid = (l + r) >> 1;
    this.build(a, 2 * node, l, mid);
    this.build(a, 2 * node + 1, mid + 1, r);
    this.tree[node] = (this.tree[2 * node] as number) + (this.tree[2 * node + 1] as number);
  }
}

