class MinSeg {
  n: number;
  t: number[];
  constructor(a: number[]) {
    this.n = a.length;
    this.t = new Array<number>(2 * this.n).fill(Infinity);
    a.forEach((v, i) => { this.t[this.n + i] = v; });
    for (let i = this.n - 1; i >= 1; i--) {
      this.t[i] = Math.min(this.t[2 * i] as number, this.t[2 * i + 1] as number);
    }
  }
  query(l: number, r: number): number {
    let res = Infinity;
    for (l += this.n, r += this.n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) res = Math.min(res, this.t[l++] as number);
      if (r & 1) res = Math.min(res, this.t[--r] as number);
    }
    return res;
  }
}

