static int orangesRotting(int[][] grid) {
  int m = grid.length, n = grid[0].length, fresh = 0, minutes = 0;
  Deque<int[]> queue = new ArrayDeque<>();
  for (int r = 0; r < m; r++)
    for (int c = 0; c < n; c++) {
      if (grid[r][c] == 2) queue.offer(new int[] {r, c});
      else if (grid[r][c] == 1) fresh++;
    }
  int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
  while (!queue.isEmpty() && fresh > 0) {
    for (int size = queue.size(); size > 0; size--) {
      int[] cell = queue.poll();
      for (int[] d : dirs) {
        int r = cell[0] + d[0], c = cell[1] + d[1];
        if (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] == 1) {
          grid[r][c] = 2;
          fresh--;
          queue.offer(new int[] {r, c});
        }
      }
    }
    minutes++;
  }
  return fresh == 0 ? minutes : -1;
}

class BuildTree {
  private int pre;
  private int[] preorder;
  private final Map<Integer, Integer> inIndex = new HashMap<>();
  TreeNode buildTree(int[] preorder, int[] inorder) {
    this.preorder = preorder;
    pre = 0;
    inIndex.clear();
    for (int i = 0; i < inorder.length; i++) inIndex.put(inorder[i], i);
    return build(0, inorder.length - 1);
  }
  private TreeNode build(int lo, int hi) {
    if (lo > hi) return null;
    TreeNode root = new TreeNode(preorder[pre++]);
    int mid = inIndex.get(root.val);
    root.left = build(lo, mid - 1);
    root.right = build(mid + 1, hi);
    return root;
  }
}

final class LazyHeap {
  private final PriorityQueue<Integer> heap = new PriorityQueue<>();
  private final Map<Integer, Integer> removed = new HashMap<>();
  private int size;
  void add(int x) { heap.offer(x); size++; }
  void remove(int x) { removed.merge(x, 1, Integer::sum); size--; } // x must be present
  int peek() { prune(); return heap.peek(); } // call only when size() > 0
  int size() { return size; }
  private void prune() {
    while (!heap.isEmpty() && removed.getOrDefault(heap.peek(), 0) > 0) {
      removed.merge(heap.poll(), -1, Integer::sum);
    }
  }
}

static int findMaximumXOR(int[] nums) {
  int[][] next = new int[nums.length * 31 + 1][2]; // node -> child for bit 0 and bit 1
  int count = 1, best = 0;
  for (int x : nums) {
    int node = 0;
    for (int b = 30; b >= 0; b--) {
      int bit = (x >> b) & 1;
      if (next[node][bit] == 0) next[node][bit] = count++;
      node = next[node][bit];
    }
    node = 0;
    int xor = 0;
    for (int b = 30; b >= 0; b--) {
      int bit = (x >> b) & 1;
      if (next[node][bit ^ 1] != 0) { xor |= 1 << b; node = next[node][bit ^ 1]; }
      else node = next[node][bit];
    }
    best = Math.max(best, xor);
  }
  return best;
}

