function hasCycle(n, adj) {
  const state = new Array(n).fill(0);
  const dfs = u => {
    if (state[u] === 1) return true;  // back on the current path: a cycle
    if (state[u] === 2) return false; // finished earlier: no cycle through here
    state[u] = 1;
    for (const v of adj[u]) if (dfs(v)) return true;
    state[u] = 2;
    return false;
  };
  for (let i = 0; i < n; i++) if (dfs(i)) return true;
  return false;
}

function topoOrder(n, edges) {
  const adj = Array.from({ length: n }, () => []);
  const indegree = new Array(n).fill(0);
  for (const [u, v] of edges) { adj[u].push(v); indegree[v]++; }
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  const order = [];
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    order.push(u);
    for (const v of adj[u]) if (--indegree[v] === 0) queue.push(v);
  }
  return order.length === n ? order : [];
}

