static int greedyCoins(int[] coins, int amount) {
  int[] c = coins.clone();
  Arrays.sort(c);
  int count = 0;
  for (int i = c.length - 1; i >= 0; i--) { count += amount / c[i]; amount %= c[i]; }
  return amount == 0 ? count : -1;
}
// greedyCoins(new int[]{1, 3, 4}, 6) is 3, but the best is 2

