static int minCoins(int[] coins, int amount) {
  int[] dp = new int[amount + 1];
  Arrays.fill(dp, amount + 1);
  dp[0] = 0;
  for (int a = 1; a <= amount; a++)
    for (int c : coins) if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
  return dp[amount] > amount ? -1 : dp[amount];
}

static int[][] merge(int[][] intervals) {
  int[][] a = intervals.clone();
  Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
  List<int[]> out = new ArrayList<>();
  for (int[] iv : a) {
    int[] last = out.isEmpty() ? null : out.get(out.size() - 1);
    if (last != null && iv[0] <= last[1]) last[1] = Math.max(last[1], iv[1]);
    else out.add(new int[]{iv[0], iv[1]});
  }
  return out.toArray(new int[0][]);
}

static int maxNonOverlapping(int[][] iv) {
  int[][] a = iv.clone();
  Arrays.sort(a, (x, y) -> Integer.compare(x[1], y[1]));
  long end = Long.MIN_VALUE;
  int count = 0;
  for (int[] x : a) {
    if (x[0] >= end) { count++; end = x[1]; }
  }
  return count;
}

